    for i0 in range(Hh-S.shape[0]+1):
        for j0 in range(Ww-S.shape[1]+1):
            tot=bad=0
            for a in range(S.shape[0]):
                for b in range(S.shape[1]):
                    i2,j2=i0+a,j0+b
                    if I[i2,j2]!=8:
                        tot+=1
                        if I[i2,j2]!=S[a,b]: bad+=1
            if bad<=tot and bad/tot<.5: best.append((bad/tot,tot,i0,j0))
    best.sort(); return best[:6]
for name,I,O in [('d1',I1,O1),('d2',I2,O2)]:
